create table d_margin_plan(id string comment '履保方案id',key_ctpty_id string comment '交易对手id',plan_code string comment '履保方案编号',mark_market string comment '盯市类型,数据字典：逐笔|组合',underlying_scope string comment '标的范围,数据字典：流通|限售|混合',joint_type string comment '连带担保类型,数据字典：无|自然人|管理人',monitor_pattern string comment '履保模式,数据字典：市值|名义本金',deduction_pattern string comment '抵扣模式,数据字典：抵扣|不抵扣',fee_spin_off string comment '估值报告期权费分拆, 数据字段: 是|否',float_profit_open string comment '是否浮盈开仓',charge_pattern string comment '费用收取模式,数据字典：固定|加权平均',ctpty_guarantee_id string comment '交易对手履保协议id',signature_date string comment '签署日期',created_by string comment '创建人',created_datetime string comment '创建时间',updated_by string comment '更新人',updated_datetime string comment '更新时间',is_deleted string comment '删除标识,数据字典：否｜是',plan_status string comment '方案状态',data_time string comment '【AI】数据时间',need_margin string comment '是否履保',need_allocate_cap_acct string comment '是否指定资金账户',auto_remargin string comment '自动追保',auto_withdraw string comment '自动提保',auto_margin_op_time string comment '自动追提保时间',monitor_product_valuation string comment '是否监控估值',department string comment '交易对手所属部门',plan_property string comment '方案属性',special_plan_remark string comment '特批方案备注',receiver_min_amount string comment '接收方最小转移金额',pay_min_amount string comment '支付方最小转移金额',ultra_contract_id string comment '大合约编号id',margin_collateral_type string comment '履约担保品类型',option_swap_fee_ratio string comment '券抵期权费比例系数',plan_group_id string comment '模板分组ID',is_allmarket_pb string comment '是否属于一站通,数据字典：否｜是',custom_ratio string comment '客户系数',margin_type string comment '履保类型',trs_structure_type string comment 'TRS合约结构',auto_update_margin_line string comment '自动更新履保线',early_lock_pl string comment '气囊X提前锁定收益开关 N:不支持；Y:支持',group_ctpty_id string comment '管理人交易对手id') partitioned by (busi_date string) row format delimited fields terminated by ',' stored as textfile;
